// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 oracleVersion) public {
        // Bound the oracle version to a valid non-zero value
        oracleVersion = bound(oracleVersion, 1, type(uint256).max);

        // Call currentVersion and check that the price is not zero (unless it reverts, but it shouldn't)
        (bool success, bytes memory data) = address(c).staticcall(abi.encodeWithSignature("currentVersion()"));

        // If the call succeeds, the price should never be zero (since the reference oracle returns non-zero)
        // The buggy version always returns zero price
        if (success) {
            (uint256 version, uint256 timestamp, int256 price) = abi.decode(data, (uint256, uint256, int256));
            assertTrue(price != 0, "Price should not be zero");
        }
    }
}

